// bool = True | False  ——两个构造子
const True = { tag: 'True' };
const False = { tag: 'False' };

// 「match」布尔 = 用这个类型定义的唯一消去方式
const matchBool = (b, onTrue, onFalse) =>
  b.tag === 'True' ? onTrue() : onFalse();

// if 就是它
const IF = (b, t, f) => matchBool(b, () => t, () => f);

// 现在你能写一个「三值」类型，if 就无能为力了
const Result = tag => v => ({ tag, v });
const matchResult = (r, onOk, onErr, onPending) =>
  ({ Ok: onOk, Err: onErr, Pending: onPending })[r.tag](r.v);

matchResult(Result('Pending')(null),
  v => 'ok ' + v, v => 'err ' + v, () => 'pending…')

// while (i < n) { acc += i; i++ }
const sumLoop = n => {
  const go = (i, acc) => i >= n ? acc : go(i + 1, acc + i);
  return go(0, 0);
};
sumLoop(10)

const fold = xs => init => f => xs.reduce(f, init);

const map     = xs => g => fold(xs)([])((a, x) => [...a, g(x)]);
const filter  = xs => p => fold(xs)([])((a, x) => p(x) ? [...a, x] : a);
const length  = xs => fold(xs)(0)((n) => n + 1);
const reverse = xs => fold(xs)([])((a, x) => [x, ...a]);
const concat  = xss => fold(xss)([])((a, x) => [...a, ...x]);

const xs = [1,2,3,4];
({
  map: map(xs)(x => x * 2),
  filter: filter(xs)(x => x % 2 === 0),
  length: length(xs),
  reverse: reverse(xs),
  concat: concat([[1],[2,3],[4]])
})

const rps = (a, b) => {
  if (a === b) return 0;
  const beats = { rock: 'scissors', scissors: 'paper', paper: 'rock' };
  return beats[a] === b ? -1 : 1;
};

// 同一个集合，不同初始顺序 → 不同结果
['rock','paper','scissors'].sort(rps)
['paper','scissors','rock'].sort(rps)
['scissors','rock','paper'].sort(rps)
